const std = @import("std");
const mem = std.mem;
const net = std.net;
const crypto = std.crypto;
const json = std.json;
const fmt = std.fmt;
const process = std.process;
const Thread = std.Thread;
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const posix = std.posix;

const index_html = @embedFile("index.html");

const LISTEN_PORT: u16 = 8080;
const MAX_ITERATIONS: u32 = 40;
const CHROME_DEBUG_PORT: u16 = 9222;
const FIREWORKS_HOST = "api.fireworks.ai";
const FIREWORKS_MODEL = "accounts/fireworks/models/minimax-m2p7";
const CHROME_UA = "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/138.0.0.0 Safari/537.36";

var gpa = std.heap.GeneralPurposeAllocator(.{}){};
var run_registry: RunRegistry = undefined;
var chrome_child: ?process.Child = null;
var chrome_mutex: Thread.Mutex = .{};

// =========================================================
// SseQueue
// =========================================================

const SseQueue = struct {
    allocator: Allocator,
    items: ArrayList([]const u8),
    mutex: Thread.Mutex,
    cond: Thread.Condition,
    done: bool,

    fn init(allocator: Allocator) SseQueue {
        return .{
            .allocator = allocator,
            .items = ArrayList([]const u8).init(allocator),
            .mutex = .{},
            .cond = .{},
            .done = false,
        };
    }

    fn deinit(self: *SseQueue) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        for (self.items.items) |item| self.allocator.free(item);
        self.items.deinit();
    }

    fn push(self: *SseQueue, msg: []const u8) void {
        const owned = self.allocator.dupe(u8, msg) catch return;
        self.mutex.lock();
        defer self.mutex.unlock();
        self.items.append(owned) catch {
            self.allocator.free(owned);
            return;
        };
        self.cond.signal();
    }

    fn drain(self: *SseQueue, out: *ArrayList([]const u8)) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        for (self.items.items) |item| {
            out.append(item) catch {
                self.allocator.free(item);
            };
        }
        self.items.clearRetainingCapacity();
    }

    fn finish(self: *SseQueue) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        self.done = true;
        self.cond.broadcast();
    }

    fn isDone(self: *SseQueue) bool {
        self.mutex.lock();
        defer self.mutex.unlock();
        return self.done;
    }
};

// =========================================================
// AgentRun
// =========================================================

const AgentRun = struct {
    allocator: Allocator,
    id: []const u8,
    task: []const u8,
    current_url: []u8,
    iteration: u32,
    max_iterations: u32,
    last_action: []u8,
    running: std.atomic.Value(bool),
    sse_queue: SseQueue,

    fn init(allocator: Allocator, id: []const u8, task: []const u8) !*AgentRun {
        const run = try allocator.create(AgentRun);
        run.* = AgentRun{
            .allocator = allocator,
            .id = try allocator.dupe(u8, id),
            .task = try allocator.dupe(u8, task),
            .current_url = try allocator.dupe(u8, "about:blank"),
            .iteration = 0,
            .max_iterations = MAX_ITERATIONS,
            .last_action = try allocator.dupe(u8, "none"),
            .running = std.atomic.Value(bool).init(true),
            .sse_queue = SseQueue.init(allocator),
        };
        return run;
    }

    fn setCurrentUrl(self: *AgentRun, url: []const u8) void {
        self.allocator.free(self.current_url);
        self.current_url = self.allocator.dupe(u8, url) catch self.current_url;
    }

    fn setLastAction(self: *AgentRun, action: []const u8) void {
        self.allocator.free(self.last_action);
        self.last_action = self.allocator.dupe(u8, action) catch self.last_action;
    }

    fn deinit(self: *AgentRun) void {
        self.sse_queue.deinit();
        self.allocator.free(self.id);
        self.allocator.free(self.task);
        self.allocator.free(self.current_url);
        self.allocator.free(self.last_action);
        self.allocator.destroy(self);
    }
};

// =========================================================
// RunRegistry
// =========================================================

const RunRegistry = struct {
    map: std.StringHashMap(*AgentRun),
    lock: Thread.RwLock,

    fn init(allocator: Allocator) RunRegistry {
        return .{
            .map = std.StringHashMap(*AgentRun).init(allocator),
            .lock = .{},
        };
    }

    fn register(self: *RunRegistry, run: *AgentRun) !void {
        self.lock.lock();
        defer self.lock.unlock();
        try self.map.put(run.id, run);
    }

    fn get(self: *RunRegistry, id: []const u8) ?*AgentRun {
        self.lock.lockShared();
        defer self.lock.unlockShared();
        return self.map.get(id);
    }

    fn remove(self: *RunRegistry, id: []const u8) void {
        self.lock.lock();
        defer self.lock.unlock();
        _ = self.map.remove(id);
    }
};

// =========================================================
// UUID v4 generation
// =========================================================

fn generateRunId(buf: *[36]u8) void {
    var bytes: [16]u8 = undefined;
    crypto.random.bytes(&bytes);
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    _ = fmt.bufPrint(buf, "{x:0>2}{x:0>2}{x:0>2}{x:0>2}-{x:0>2}{x:0>2}-{x:0>2}{x:0>2}-{x:0>2}{x:0>2}-{x:0>2}{x:0>2}{x:0>2}{x:0>2}{x:0>2}{x:0>2}", .{
        bytes[0],  bytes[1],  bytes[2],  bytes[3],
        bytes[4],  bytes[5],  bytes[6],  bytes[7],
        bytes[8],  bytes[9],  bytes[10], bytes[11],
        bytes[12], bytes[13], bytes[14], bytes[15],
    }) catch {};
}

// =========================================================
// HTTP helpers
// =========================================================

const HttpRequest = struct {
    method: []const u8,
    path: []const u8,
    query: []const u8,
    body: []const u8,
    allocator: Allocator,

    fn deinit(self: *HttpRequest) void {
        if (self.body.len > 0) self.allocator.free(self.body);
    }
};

fn parseQuery(query: []const u8, key: []const u8) ?[]const u8 {
    var it = mem.tokenizeScalar(u8, query, '&');
    while (it.next()) |part| {
        if (mem.startsWith(u8, part, key)) {
            const rest = part[key.len..];
            if (rest.len > 0 and rest[0] == '=') return rest[1..];
        }
    }
    return null;
}

fn parseJsonField(allocator: Allocator, body: []const u8, field: []const u8) ?[]const u8 {
    var needle_buf: [256]u8 = undefined;
    const needle = fmt.bufPrint(&needle_buf, "\"{s}\"", .{field}) catch return null;
    const pos = mem.indexOf(u8, body, needle) orelse return null;
    const after_key = pos + needle.len;
    if (after_key >= body.len) return null;
    var i = after_key;
    while (i < body.len and (body[i] == ' ' or body[i] == ':')) i += 1;
    if (i >= body.len) return null;
    if (body[i] == '"') {
        i += 1;
        const start = i;
        while (i < body.len and body[i] != '"') {
            if (body[i] == '\\') i += 1;
            i += 1;
        }
        const raw = body[start..i];
        var result = ArrayList(u8).init(allocator);
        var j: usize = 0;
        while (j < raw.len) {
            if (raw[j] == '\\' and j + 1 < raw.len) {
                switch (raw[j + 1]) {
                    'n' => result.append('\n') catch {},
                    'r' => result.append('\r') catch {},
                    't' => result.append('\t') catch {},
                    '"' => result.append('"') catch {},
                    '\\' => result.append('\\') catch {},
                    else => {
                        result.append('\\') catch {};
                        result.append(raw[j + 1]) catch {};
                    },
                }
                j += 2;
            } else {
                result.append(raw[j]) catch {};
                j += 1;
            }
        }
        return result.toOwnedSlice() catch null;
    }
    return null;
}

fn writeHttpResponse(stream: net.Stream, status: u16, content_type: []const u8, body: []const u8, allocator: Allocator) void {
    const status_text = switch (status) {
        200 => "OK",
        204 => "No Content",
        400 => "Bad Request",
        404 => "Not Found",
        500 => "Internal Server Error",
        else => "OK",
    };
    const response = fmt.allocPrint(allocator, "HTTP/1.1 {d} {s}\r\nContent-Type: {s}\r\nContent-Length: {d}\r\nAccess-Control-Allow-Origin: *\r\nConnection: close\r\n\r\n", .{ status, status_text, content_type, body.len }) catch return;
    defer allocator.free(response);
    _ = stream.writeAll(response) catch {};
    _ = stream.writeAll(body) catch {};
}

fn writeSSEHeaders(stream: net.Stream, allocator: Allocator) void {
    const headers = fmt.allocPrint(allocator, "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nCache-Control: no-cache\r\nConnection: keep-alive\r\nAccess-Control-Allow-Origin: *\r\n\r\n", .{}) catch return;
    defer allocator.free(headers);
    _ = stream.writeAll(headers) catch {};
}

fn parseHttpRequest(stream: net.Stream, allocator: Allocator) !HttpRequest {
    var header_buf: [8192]u8 = undefined;
    var header_len: usize = 0;
    while (header_len < header_buf.len - 1) {
        var one: [1]u8 = undefined;
        const n = stream.read(&one) catch break;
        if (n == 0) break;
        header_buf[header_len] = one[0];
        header_len += 1;
        if (header_len >= 4 and mem.eql(u8, header_buf[header_len - 4 .. header_len], "\r\n\r\n")) break;
    }
    const raw = header_buf[0..header_len];
    const first_line_end = mem.indexOf(u8, raw, "\r\n") orelse return error.BadRequest;
    const first_line = raw[0..first_line_end];
    var parts = mem.tokenizeScalar(u8, first_line, ' ');
    const method = parts.next() orelse return error.BadRequest;
    const full_path = parts.next() orelse return error.BadRequest;

    const path_end = mem.indexOf(u8, full_path, "?") orelse full_path.len;
    const path = full_path[0..path_end];
    const query = if (path_end < full_path.len) full_path[path_end + 1 ..] else "";

    var content_length: usize = 0;
    var lines_iter = mem.splitSequence(u8, raw[first_line_end + 2 ..], "\r\n");
    while (lines_iter.next()) |line| {
        if (line.len == 0) break;
        const colon = mem.indexOf(u8, line, ":") orelse continue;
        const hname = mem.trim(u8, line[0..colon], " ");
        const hval = mem.trim(u8, line[colon + 1 ..], " ");
        if (std.ascii.eqlIgnoreCase(hname, "content-length")) {
            content_length = fmt.parseInt(usize, hval, 10) catch 0;
        }
    }

    var body: []const u8 = &[_]u8{};
    if (content_length > 0 and content_length <= 1024 * 1024) {
        const body_buf = try allocator.alloc(u8, content_length);
        var read_total: usize = 0;
        while (read_total < content_length) {
            const n = stream.read(body_buf[read_total..]) catch break;
            if (n == 0) break;
            read_total += n;
        }
        body = body_buf[0..read_total];
    }

    return HttpRequest{
        .method = method,
        .path = path,
        .query = query,
        .body = body,
        .allocator = allocator,
    };
}

// =========================================================
// Handle connection
// =========================================================

const ConnArgs = struct {
    conn: net.Server.Connection,
};

fn handleConn(args: ConnArgs) void {
    var arena = std.heap.ArenaAllocator.init(gpa.allocator());
    defer arena.deinit();
    const allocator = arena.allocator();
    const stream = args.conn.stream;
    defer stream.close();

    var req = parseHttpRequest(stream, allocator) catch {
        writeHttpResponse(stream, 400, "text/plain", "Bad Request", allocator);
        return;
    };
    defer req.deinit();

    if (mem.eql(u8, req.path, "/") or mem.eql(u8, req.path, "")) {
        writeHttpResponse(stream, 200, "text/html; charset=utf-8", index_html, allocator);
    } else if (mem.eql(u8, req.path, "/favicon.ico")) {
        writeHttpResponse(stream, 204, "text/plain", "", allocator);
    } else if (mem.eql(u8, req.path, "/task") and mem.eql(u8, req.method, "POST")) {
        handleTaskPost(stream, &req, allocator);
    } else if (mem.eql(u8, req.path, "/events")) {
        handleEvents(stream, &req, allocator);
    } else if (mem.eql(u8, req.path, "/status")) {
        handleStatus(stream, &req, allocator);
    } else if (mem.eql(u8, req.path, "/stop")) {
        handleStop(stream, &req, allocator);
    } else if (mem.eql(u8, req.path, "/api/agent") and mem.eql(u8, req.method, "POST")) {
        handleApiAgent(stream, &req, allocator);
    } else if (mem.eql(u8, req.path, "/api/chat") and mem.eql(u8, req.method, "POST")) {
        handleApiChat(stream, &req, allocator);
    } else if (mem.eql(u8, req.path, "/screenshot")) {
        handleScreenshot(stream, &req, allocator);
    } else {
        writeHttpResponse(stream, 404, "text/plain", "Not Found", allocator);
    }
}

fn handleTaskPost(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const task = parseJsonField(allocator, req.body, "task") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing task\"}", allocator);
        return;
    };
    defer allocator.free(task);

    var id_buf: [36]u8 = undefined;
    generateRunId(&id_buf);
    const run_id = &id_buf;

    const run = AgentRun.init(gpa.allocator(), run_id, task) catch {
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"internal error\"}", allocator);
        return;
    };

    run_registry.register(run) catch {
        run.deinit();
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"registry error\"}", allocator);
        return;
    };

    const thread = Thread.spawn(.{}, agentLoop, .{run}) catch {
        run_registry.remove(run.id);
        run.deinit();
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"spawn error\"}", allocator);
        return;
    };
    thread.detach();

    const resp = fmt.allocPrint(allocator, "{{\"status\":\"started\",\"id\":\"{s}\"}}", .{run_id}) catch return;
    defer allocator.free(resp);
    writeHttpResponse(stream, 200, "application/json", resp, allocator);
}

fn handleEvents(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const run_id = parseQuery(req.query, "id") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing id\"}", allocator);
        return;
    };
    const run = run_registry.get(run_id) orelse {
        writeHttpResponse(stream, 404, "application/json", "{\"error\":\"not found\"}", allocator);
        return;
    };

    writeSSEHeaders(stream, allocator);

    var buf = ArrayList([]const u8).init(allocator);
    defer {
        for (buf.items) |item| gpa.allocator().free(item);
        buf.deinit();
    }

    while (true) {
        run.sse_queue.drain(&buf);
        for (buf.items) |item| {
            const line = fmt.allocPrint(allocator, "data: {s}\n\n", .{item}) catch continue;
            defer allocator.free(line);
            stream.writeAll(line) catch return;
            gpa.allocator().free(item);
        }
        buf.clearRetainingCapacity();

        if (run.sse_queue.isDone()) {
            _ = stream.writeAll("data: {\"type\":\"done\"}\n\n") catch {};
            return;
        }

        std.time.sleep(200 * std.time.ns_per_ms);
    }
}

fn handleStatus(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const run_id = parseQuery(req.query, "id") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing id\"}", allocator);
        return;
    };
    const run = run_registry.get(run_id) orelse {
        writeHttpResponse(stream, 404, "application/json", "{\"error\":\"not found\"}", allocator);
        return;
    };

    const resp = fmt.allocPrint(allocator, "{{\"running\":{s},\"iteration\":{d},\"current_url\":\"{s}\",\"last_action\":\"{s}\"}}", .{
        if (run.running.load(.seq_cst)) "true" else "false",
        run.iteration,
        run.current_url,
        run.last_action,
    }) catch return;
    defer allocator.free(resp);
    writeHttpResponse(stream, 200, "application/json", resp, allocator);
}

fn handleStop(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const run_id = parseQuery(req.query, "id") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing id\"}", allocator);
        return;
    };
    const run = run_registry.get(run_id) orelse {
        writeHttpResponse(stream, 404, "application/json", "{\"error\":\"not found\"}", allocator);
        return;
    };
    run.running.store(false, .seq_cst);
    writeHttpResponse(stream, 200, "application/json", "{\"status\":\"stopping\"}", allocator);
}

fn handleScreenshot(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    _ = req;
    var cdp = CdpClient.connect(allocator) catch {
        writeHttpResponse(stream, 503, "application/json", "{\"error\":\"cdp unavailable\"}", allocator);
        return;
    };
    defer cdp.deinit();
    const data = cdp.captureScreenshot() catch {
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"screenshot failed\"}", allocator);
        return;
    };
    defer allocator.free(data);
    const resp = fmt.allocPrint(allocator, "{{\"data\":\"{s}\"}}", .{data}) catch return;
    defer allocator.free(resp);
    writeHttpResponse(stream, 200, "application/json", resp, allocator);
}

fn handleApiAgent(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const message = parseJsonField(allocator, req.body, "message") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing message\"}", allocator);
        return;
    };
    defer allocator.free(message);

    var id_buf: [36]u8 = undefined;
    generateRunId(&id_buf);

    const run = AgentRun.init(gpa.allocator(), &id_buf, message) catch {
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"internal error\"}", allocator);
        return;
    };

    run_registry.register(run) catch {
        run.deinit();
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"registry error\"}", allocator);
        return;
    };

    const thread = Thread.spawn(.{}, agentLoop, .{run}) catch {
        run_registry.remove(run.id);
        run.deinit();
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"spawn error\"}", allocator);
        return;
    };
    thread.detach();

    writeSSEHeaders(stream, allocator);

    var buf = ArrayList([]const u8).init(allocator);
    defer {
        for (buf.items) |item| gpa.allocator().free(item);
        buf.deinit();
    }

    const run_id_evt = fmt.allocPrint(allocator, "data: {{\"type\":\"agent_run_id\",\"id\":\"{s}\"}}\n\n", .{&id_buf}) catch "";
    defer if (run_id_evt.len > 0) allocator.free(run_id_evt);
    if (run_id_evt.len > 0) _ = stream.writeAll(run_id_evt) catch {};

    const intro = fmt.allocPrint(allocator, "{{\"type\":\"content\",\"text\":\"🤖 **Agent started**: {s}\\n\\n\"}}", .{message}) catch "";
    defer if (intro.len > 0) allocator.free(intro);
    if (intro.len > 0) {
        const line = fmt.allocPrint(allocator, "data: {s}\n\n", .{intro}) catch "";
        defer if (line.len > 0) allocator.free(line);
        if (line.len > 0) _ = stream.writeAll(line) catch {};
    }

    while (true) {
        run.sse_queue.drain(&buf);
        for (buf.items) |item| {
            const wrapped = fmt.allocPrint(allocator, "data: {s}\n\n", .{item}) catch {
                gpa.allocator().free(item);
                continue;
            };
            defer allocator.free(wrapped);
            stream.writeAll(wrapped) catch {
                gpa.allocator().free(item);
                continue;
            };
            gpa.allocator().free(item);
        }
        buf.clearRetainingCapacity();

        if (run.sse_queue.isDone()) {
            _ = stream.writeAll("data: {\"type\":\"done\"}\n\n") catch {};
            return;
        }

        std.time.sleep(200 * std.time.ns_per_ms);
    }
}

fn handleApiChat(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const message = parseJsonField(allocator, req.body, "message") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing message\"}", allocator);
        return;
    };
    defer allocator.free(message);

    const api_key = process.getEnvVarOwned(allocator, "FIREWORKS_API_KEY") catch {
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"missing FIREWORKS_API_KEY\"}", allocator);
        return;
    };
    defer allocator.free(api_key);

    writeSSEHeaders(stream, allocator);

    const response = callLlmSimple(allocator, message, api_key) catch |err| blk: {
        std.debug.print("LLM error: {}\n", .{err});
        break :blk allocator.dupe(u8, "Hiba történt az AI hívás során.") catch return;
    };
    defer allocator.free(response);

    var escaped = ArrayList(u8).init(allocator);
    defer escaped.deinit();
    for (response) |c| {
        switch (c) {
            '"' => escaped.appendSlice("\\\"") catch {},
            '\\' => escaped.appendSlice("\\\\") catch {},
            '\n' => escaped.appendSlice("\\n") catch {},
            '\r' => escaped.appendSlice("\\r") catch {},
            else => escaped.append(c) catch {},
        }
    }

    const sse = fmt.allocPrint(allocator, "data: {{\"type\":\"content\",\"text\":\"{s}\"}}\n\ndata: {{\"type\":\"done\"}}\n\n", .{escaped.items}) catch return;
    defer allocator.free(sse);
    _ = stream.writeAll(sse) catch {};
}

// =========================================================
// LLM Client (Fireworks AI, HTTP/1.1 over TLS)
// =========================================================

fn callLlmSimple(allocator: Allocator, user_message: []const u8, api_key: []const u8) ![]const u8 {
    const messages_json = try fmt.allocPrint(allocator,
        \\[{{"role":"user","content":"{s}"}}]
    , .{user_message});
    defer allocator.free(messages_json);
    return callLlmWithMessages(allocator, messages_json, api_key);
}

fn escapeJsonString(allocator: Allocator, s: []const u8) ![]const u8 {
    var out = ArrayList(u8).init(allocator);
    for (s) |c| {
        switch (c) {
            '"' => try out.appendSlice("\\\""),
            '\\' => try out.appendSlice("\\\\"),
            '\n' => try out.appendSlice("\\n"),
            '\r' => try out.appendSlice("\\r"),
            '\t' => try out.appendSlice("\\t"),
            0...8, 11, 12, 14...31 => {
                var tmp: [6]u8 = undefined;
                const s2 = try fmt.bufPrint(&tmp, "\\u{x:0>4}", .{c});
                try out.appendSlice(s2);
            },
            else => try out.append(c),
        }
    }
    return out.toOwnedSlice();
}

fn decodeChunked(allocator: Allocator, data: []const u8) ![]const u8 {
    var out = ArrayList(u8).init(allocator);
    errdefer out.deinit();
    var pos: usize = 0;
    while (pos < data.len) {
