        const n = tls_client.read(tcp, &rbuf) catch break;
        if (n == 0) break;
        try response_buf.appendSlice(rbuf[0..n]);
    }

    const response = response_buf.items;
    const header_end = mem.indexOf(u8, response, "\r\n\r\n") orelse return error.InvalidResponse;
    const headers_section = response[0..header_end];
    const raw_body = response[header_end + 4 ..];

    const is_chunked = mem.indexOf(u8, headers_section, "chunked") != null;
    const resp_body = if (is_chunked)
        try decodeChunked(allocator, raw_body)
    else
        try allocator.dupe(u8, raw_body);
    defer allocator.free(resp_body);

    const content = extractLlmContent(allocator, resp_body) catch |err| {
        std.debug.print("LLM parse error: {} | status: {s} | body: {s}\n", .{
            err,
            headers_section[0..@min(headers_section.len, 60)],
            resp_body[0..@min(resp_body.len, 120)],
        });
        return error.LlmParseFailed;
    };
    return content;
}

fn extractLlmContent(allocator: Allocator, body: []const u8) ![]const u8 {
    const parsed = try json.parseFromSlice(json.Value, allocator, body, .{});
    defer parsed.deinit();

    const root = parsed.value;
    if (root != .object) return error.InvalidJson;

    const choices = root.object.get("choices") orelse return error.NoChoices;
    if (choices != .array or choices.array.items.len == 0) return error.NoChoices;

    const first = choices.array.items[0];
    if (first != .object) return error.InvalidChoice;

    const msg = first.object.get("message") orelse return error.NoMessage;
    if (msg != .object) return error.InvalidMessage;

    const content = msg.object.get("content") orelse return error.NoContent;
    if (content != .string) return error.InvalidContent;

    return allocator.dupe(u8, content.string);
}

