            i += 1;
        }
        const raw = body[start..i];
        var result = ArrayList(u8).init(allocator);
        var j: usize = 0;
        while (j < raw.len) {
            if (raw[j] == '\\' and j + 1 < raw.len) {
                switch (raw[j + 1]) {
                    'n' => result.append('\n') catch {},
                    'r' => result.append('\r') catch {},
                    't' => result.append('\t') catch {},
                    '"' => result.append('"') catch {},
                    '\\' => result.append('\\') catch {},
                    else => {
                        result.append('\\') catch {};
                        result.append(raw[j + 1]) catch {};
                    },
                }
                j += 2;
            } else {
                result.append(raw[j]) catch {};
                j += 1;
            }
        }
        return result.toOwnedSlice() catch null;
    }
    return null;
}

fn writeHttpResponse(stream: net.Stream, status: u16, content_type: []const u8, body: []const u8, allocator: Allocator) void {
    const status_text = switch (status) {
        200 => "OK",
        204 => "No Content",
        400 => "Bad Request",
        404 => "Not Found",
        500 => "Internal Server Error",
        else => "OK",
    };
    const response = fmt.allocPrint(allocator, "HTTP/1.1 {d} {s}\r\nContent-Type: {s}\r\nContent-Length: {d}\r\nAccess-Control-Allow-Origin: *\r\nConnection: close\r\n\r\n", .{ status, status_text, content_type, body.len }) catch return;
    defer allocator.free(response);
    _ = stream.writeAll(response) catch {};
    _ = stream.writeAll(body) catch {};
}

fn writeSSEHeaders(stream: net.Stream, allocator: Allocator) void {
    const headers = fmt.allocPrint(allocator, "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nCache-Control: no-cache\r\nConnection: keep-alive\r\nAccess-Control-Allow-Origin: *\r\n\r\n", .{}) catch return;
    defer allocator.free(headers);
    _ = stream.writeAll(headers) catch {};
}

fn parseHttpRequest(stream: net.Stream, allocator: Allocator) !HttpRequest {
    var header_buf: [8192]u8 = undefined;
    var header_len: usize = 0;
    while (header_len < header_buf.len - 1) {
        var one: [1]u8 = undefined;
        const n = stream.read(&one) catch break;
        if (n == 0) break;
        header_buf[header_len] = one[0];
        header_len += 1;
        if (header_len >= 4 and mem.eql(u8, header_buf[header_len - 4 .. header_len], "\r\n\r\n")) break;
    }
    const raw = header_buf[0..header_len];
    const first_line_end = mem.indexOf(u8, raw, "\r\n") orelse return error.BadRequest;
    const first_line = raw[0..first_line_end];
    var parts = mem.tokenizeScalar(u8, first_line, ' ');
    const method = parts.next() orelse return error.BadRequest;
    const full_path = parts.next() orelse return error.BadRequest;

    const path_end = mem.indexOf(u8, full_path, "?") orelse full_path.len;
    const path = full_path[0..path_end];
    const query = if (path_end < full_path.len) full_path[path_end + 1 ..] else "";

    var content_length: usize = 0;
    var lines_iter = mem.splitSequence(u8, raw[first_line_end + 2 ..], "\r\n");
    while (lines_iter.next()) |line| {
        if (line.len == 0) break;
        const colon = mem.indexOf(u8, line, ":") orelse continue;
        const hname = mem.trim(u8, line[0..colon], " ");
        const hval = mem.trim(u8, line[colon + 1 ..], " ");
        if (std.ascii.eqlIgnoreCase(hname, "content-length")) {
            content_length = fmt.parseInt(usize, hval, 10) catch 0;
        }
    }

    var body: []const u8 = &[_]u8{};
    if (content_length > 0 and content_length <= 1024 * 1024) {
        const body_buf = try allocator.alloc(u8, content_length);
        var read_total: usize = 0;
        while (read_total < content_length) {
            const n = stream.read(body_buf[read_total..]) catch break;
            if (n == 0) break;
            read_total += n;
        }
        body = body_buf[0..read_total];
    }

    return HttpRequest{
        .method = method,
        .path = path,
        .query = query,
        .body = body,
        .allocator = allocator,
    };
}

// =========================================================
// Handle connection
// =========================================================

const ConnArgs = struct {
    conn: net.Server.Connection,
};

fn handleConn(args: ConnArgs) void {
    var arena = std.heap.ArenaAllocator.init(gpa.allocator());
    defer arena.deinit();
    const allocator = arena.allocator();
    const stream = args.conn.stream;
    defer stream.close();

    var req = parseHttpRequest(stream, allocator) catch {
        writeHttpResponse(stream, 400, "text/plain", "Bad Request", allocator);
        return;
    };
    defer req.deinit();

    if (mem.eql(u8, req.path, "/") or mem.eql(u8, req.path, "")) {
        writeHttpResponse(stream, 200, "text/html; charset=utf-8", index_html, allocator);
    } else if (mem.eql(u8, req.path, "/favicon.ico")) {
        writeHttpResponse(stream, 204, "text/plain", "", allocator);
    } else if (mem.eql(u8, req.path, "/task") and mem.eql(u8, req.method, "POST")) {
        handleTaskPost(stream, &req, allocator);
    } else if (mem.eql(u8, req.path, "/events")) {
        handleEvents(stream, &req, allocator);
    } else if (mem.eql(u8, req.path, "/status")) {
        handleStatus(stream, &req, allocator);
    } else if (mem.eql(u8, req.path, "/stop")) {
        handleStop(stream, &req, allocator);
    } else if (mem.eql(u8, req.path, "/api/agent") and mem.eql(u8, req.method, "POST")) {
        handleApiAgent(stream, &req, allocator);
    } else if (mem.eql(u8, req.path, "/api/chat") and mem.eql(u8, req.method, "POST")) {
        handleApiChat(stream, &req, allocator);
    } else if (mem.eql(u8, req.path, "/screenshot")) {
        handleScreenshot(stream, &req, allocator);
    } else {
        writeHttpResponse(stream, 404, "text/plain", "Not Found", allocator);
    }
}

fn handleTaskPost(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const task = parseJsonField(allocator, req.body, "task") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing task\"}", allocator);
        return;
    };
    defer allocator.free(task);

    var id_buf: [36]u8 = undefined;
    generateRunId(&id_buf);
    const run_id = &id_buf;

    const run = AgentRun.init(gpa.allocator(), run_id, task) catch {
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"internal error\"}", allocator);
        return;
    };

    run_registry.register(run) catch {
        run.deinit();
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"registry error\"}", allocator);
        return;
    };

    const thread = Thread.spawn(.{}, agentLoop, .{run}) catch {
        run_registry.remove(run.id);
        run.deinit();
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"spawn error\"}", allocator);
        return;
    };
    thread.detach();

    const resp = fmt.allocPrint(allocator, "{{\"status\":\"started\",\"id\":\"{s}\"}}", .{run_id}) catch return;
    defer allocator.free(resp);
    writeHttpResponse(stream, 200, "application/json", resp, allocator);
}

fn handleEvents(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const run_id = parseQuery(req.query, "id") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing id\"}", allocator);
        return;
    };
    const run = run_registry.get(run_id) orelse {
        writeHttpResponse(stream, 404, "application/json", "{\"error\":\"not found\"}", allocator);
        return;
    };

    writeSSEHeaders(stream, allocator);

    var buf = ArrayList([]const u8).init(allocator);
    defer {
        for (buf.items) |item| gpa.allocator().free(item);
        buf.deinit();
    }

    while (true) {
        run.sse_queue.drain(&buf);
        for (buf.items) |item| {
            const line = fmt.allocPrint(allocator, "data: {s}\n\n", .{item}) catch continue;
            defer allocator.free(line);
            stream.writeAll(line) catch return;
            gpa.allocator().free(item);
        }
        buf.clearRetainingCapacity();

        if (run.sse_queue.isDone()) {
            _ = stream.writeAll("data: {\"type\":\"done\"}\n\n") catch {};
            return;
        }

        std.time.sleep(200 * std.time.ns_per_ms);
    }
}

fn handleStatus(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const run_id = parseQuery(req.query, "id") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing id\"}", allocator);
        return;
    };
    const run = run_registry.get(run_id) orelse {
        writeHttpResponse(stream, 404, "application/json", "{\"error\":\"not found\"}", allocator);
        return;
    };

    const resp = fmt.allocPrint(allocator, "{{\"running\":{s},\"iteration\":{d},\"current_url\":\"{s}\",\"last_action\":\"{s}\"}}", .{
        if (run.running.load(.seq_cst)) "true" else "false",
        run.iteration,
        run.current_url,
        run.last_action,
    }) catch return;
    defer allocator.free(resp);
    writeHttpResponse(stream, 200, "application/json", resp, allocator);
}

fn handleStop(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const run_id = parseQuery(req.query, "id") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing id\"}", allocator);
        return;
    };
    const run = run_registry.get(run_id) orelse {
        writeHttpResponse(stream, 404, "application/json", "{\"error\":\"not found\"}", allocator);
        return;
    };
    run.running.store(false, .seq_cst);
    writeHttpResponse(stream, 200, "application/json", "{\"status\":\"stopping\"}", allocator);
}

fn handleScreenshot(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    _ = req;
    var cdp = CdpClient.connect(allocator) catch {
        writeHttpResponse(stream, 503, "application/json", "{\"error\":\"cdp unavailable\"}", allocator);
        return;
    };
    defer cdp.deinit();
    const data = cdp.captureScreenshot() catch {
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"screenshot failed\"}", allocator);
        return;
    };
    defer allocator.free(data);
    const resp = fmt.allocPrint(allocator, "{{\"data\":\"{s}\"}}", .{data}) catch return;
    defer allocator.free(resp);
    writeHttpResponse(stream, 200, "application/json", resp, allocator);
}

fn handleApiAgent(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const message = parseJsonField(allocator, req.body, "message") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing message\"}", allocator);
        return;
    };
    defer allocator.free(message);

    var id_buf: [36]u8 = undefined;
    generateRunId(&id_buf);

    const run = AgentRun.init(gpa.allocator(), &id_buf, message) catch {
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"internal error\"}", allocator);
        return;
    };

    run_registry.register(run) catch {
        run.deinit();
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"registry error\"}", allocator);
        return;
    };

    const thread = Thread.spawn(.{}, agentLoop, .{run}) catch {
        run_registry.remove(run.id);
        run.deinit();
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"spawn error\"}", allocator);
        return;
    };
    thread.detach();

    writeSSEHeaders(stream, allocator);

    var buf = ArrayList([]const u8).init(allocator);
    defer {
        for (buf.items) |item| gpa.allocator().free(item);
        buf.deinit();
    }

    const run_id_evt = fmt.allocPrint(allocator, "data: {{\"type\":\"agent_run_id\",\"id\":\"{s}\"}}\n\n", .{&id_buf}) catch "";
    defer if (run_id_evt.len > 0) allocator.free(run_id_evt);
    if (run_id_evt.len > 0) _ = stream.writeAll(run_id_evt) catch {};

    const intro = fmt.allocPrint(allocator, "{{\"type\":\"content\",\"text\":\"🤖 **Agent started**: {s}\\n\\n\"}}", .{message}) catch "";
    defer if (intro.len > 0) allocator.free(intro);
    if (intro.len > 0) {
        const line = fmt.allocPrint(allocator, "data: {s}\n\n", .{intro}) catch "";
        defer if (line.len > 0) allocator.free(line);
        if (line.len > 0) _ = stream.writeAll(line) catch {};
    }

    while (true) {
        run.sse_queue.drain(&buf);
        for (buf.items) |item| {
            const wrapped = fmt.allocPrint(allocator, "data: {s}\n\n", .{item}) catch {
                gpa.allocator().free(item);
                continue;
            };
            defer allocator.free(wrapped);
            stream.writeAll(wrapped) catch {
                gpa.allocator().free(item);
                continue;
            };
            gpa.allocator().free(item);
        }
        buf.clearRetainingCapacity();

        if (run.sse_queue.isDone()) {
            _ = stream.writeAll("data: {\"type\":\"done\"}\n\n") catch {};
            return;
        }

        std.time.sleep(200 * std.time.ns_per_ms);
    }
}

fn handleApiChat(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const message = parseJsonField(allocator, req.body, "message") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing message\"}", allocator);
        return;
    };
    defer allocator.free(message);

    const api_key = process.getEnvVarOwned(allocator, "FIREWORKS_API_KEY") catch {
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"missing FIREWORKS_API_KEY\"}", allocator);
        return;
    };
    defer allocator.free(api_key);

    writeSSEHeaders(stream, allocator);

    const response = callLlmSimple(allocator, message, api_key) catch |err| blk: {
        std.debug.print("LLM error: {}\n", .{err});
        break :blk allocator.dupe(u8, "Hiba történt az AI hívás során.") catch return;
    };
    defer allocator.free(response);

    var escaped = ArrayList(u8).init(allocator);
    defer escaped.deinit();
    for (response) |c| {
        switch (c) {
            '"' => escaped.appendSlice("\\\"") catch {},
            '\\' => escaped.appendSlice("\\\\") catch {},
            '\n' => escaped.appendSlice("\\n") catch {},
            '\r' => escaped.appendSlice("\\r") catch {},
            else => escaped.append(c) catch {},
        }
    }

    const sse = fmt.allocPrint(allocator, "data: {{\"type\":\"content\",\"text\":\"{s}\"}}\n\ndata: {{\"type\":\"done\"}}\n\n", .{escaped.items}) catch return;
    defer allocator.free(sse);
    _ = stream.writeAll(sse) catch {};
}

// =========================================================
// LLM Client (Fireworks AI, HTTP/1.1 over TLS)
// =========================================================

fn callLlmSimple(allocator: Allocator, user_message: []const u8, api_key: []const u8) ![]const u8 {
    const messages_json = try fmt.allocPrint(allocator,
        \\[{{"role":"user","content":"{s}"}}]
    , .{user_message});
    defer allocator.free(messages_json);
    return callLlmWithMessages(allocator, messages_json, api_key);
}

fn escapeJsonString(allocator: Allocator, s: []const u8) ![]const u8 {
    var out = ArrayList(u8).init(allocator);
    for (s) |c| {
        switch (c) {
            '"' => try out.appendSlice("\\\""),
            '\\' => try out.appendSlice("\\\\"),
            '\n' => try out.appendSlice("\\n"),
            '\r' => try out.appendSlice("\\r"),
            '\t' => try out.appendSlice("\\t"),
            0...8, 11, 12, 14...31 => {
                var tmp: [6]u8 = undefined;
                const s2 = try fmt.bufPrint(&tmp, "\\u{x:0>4}", .{c});
                try out.appendSlice(s2);
            },
            else => try out.append(c),
        }
    }
    return out.toOwnedSlice();
}

fn decodeChunked(allocator: Allocator, data: []const u8) ![]const u8 {
    var out = ArrayList(u8).init(allocator);
    errdefer out.deinit();
    var pos: usize = 0;
    while (pos < data.len) {
        const crlf = mem.indexOf(u8, data[pos..], "\r\n") orelse break;
        const size_str = mem.trim(u8, data[pos .. pos + crlf], " \t");
        if (size_str.len == 0) break;
        const chunk_size = fmt.parseInt(usize, size_str, 16) catch break;
        if (chunk_size == 0) break;
        pos += crlf + 2;
        if (pos + chunk_size > data.len) {
            try out.appendSlice(data[pos..]);
            break;
        }
        try out.appendSlice(data[pos .. pos + chunk_size]);
        pos += chunk_size + 2;
    }
    return out.toOwnedSlice();
}

fn callLlmWithMessages(allocator: Allocator, messages_json: []const u8, api_key: []const u8) ![]const u8 {
    const body = try fmt.allocPrint(allocator,
        \\{{"model":"{s}","max_tokens":4096,"top_p":1,"top_k":40,"presence_penalty":0,"frequency_penalty":0,"temperature":0.6,"messages":{s}}}
    , .{ FIREWORKS_MODEL, messages_json });
    defer allocator.free(body);

    const auth_header = try fmt.allocPrint(allocator, "Bearer {s}", .{api_key});
    defer allocator.free(auth_header);

    const request = try fmt.allocPrint(allocator,
        "POST /inference/v1/chat/completions HTTP/1.1\r\n" ++
            "Host: {s}\r\n" ++
            "Content-Type: application/json\r\n" ++
            "Authorization: {s}\r\n" ++
            "Content-Length: {d}\r\n" ++
            "Connection: close\r\n" ++
            "\r\n",
        .{ FIREWORKS_HOST, auth_header, body.len },
    );
    defer allocator.free(request);

    const tcp = try net.tcpConnectToHost(allocator, FIREWORKS_HOST, 443);
    defer tcp.close();

    var ca_bundle: crypto.Certificate.Bundle = .{};
    try ca_bundle.rescan(allocator);
    defer ca_bundle.deinit(allocator);

    var tls_client = try crypto.tls.Client.init(tcp, .{
        .host = .{ .explicit = FIREWORKS_HOST },
        .ca = .{ .bundle = ca_bundle },
    });

    try tls_client.writeAll(tcp, request);
    try tls_client.writeAll(tcp, body);

    var response_buf = ArrayList(u8).init(allocator);
    defer response_buf.deinit();
    var rbuf: [4096]u8 = undefined;
    while (true) {
        const n = tls_client.read(tcp, &rbuf) catch break;
        if (n == 0) break;
        try response_buf.appendSlice(rbuf[0..n]);
    }

    const response = response_buf.items;
    const header_end = mem.indexOf(u8, response, "\r\n\r\n") orelse return error.InvalidResponse;
    const headers_section = response[0..header_end];
    const raw_body = response[header_end + 4 ..];

    const is_chunked = mem.indexOf(u8, headers_section, "chunked") != null;
    const resp_body = if (is_chunked)
        try decodeChunked(allocator, raw_body)
    else
        try allocator.dupe(u8, raw_body);
    defer allocator.free(resp_body);

    const content = extractLlmContent(allocator, resp_body) catch |err| {
        std.debug.print("LLM parse error: {} | status: {s} | body: {s}\n", .{
            err,
            headers_section[0..@min(headers_section.len, 60)],
            resp_body[0..@min(resp_body.len, 120)],
        });
        return error.LlmParseFailed;
    };
    return content;
}

fn extractLlmContent(allocator: Allocator, body: []const u8) ![]const u8 {
    const parsed = try json.parseFromSlice(json.Value, allocator, body, .{});
    defer parsed.deinit();

    const root = parsed.value;
    if (root != .object) return error.InvalidJson;

    const choices = root.object.get("choices") orelse return error.NoChoices;
    if (choices != .array or choices.array.items.len == 0) return error.NoChoices;

    const first = choices.array.items[0];
    if (first != .object) return error.InvalidChoice;

    const msg = first.object.get("message") orelse return error.NoMessage;
    if (msg != .object) return error.InvalidMessage;

    const content = msg.object.get("content") orelse return error.NoContent;
    if (content != .string) return error.InvalidContent;

    return allocator.dupe(u8, content.string);
}

fn callLlmForAgent(allocator: Allocator, task: []const u8, current_url: []const u8, page_title: []const u8, iteration: u32, history: []const u8, dom_snapshot: []const u8, api_key: []const u8) ![]const u8 {
    const system_prompt =
        \\You are a browser automation agent. You receive the current browser state and must respond with a single JSON object describing the next action. You must always respond with valid JSON only, no prose, no markdown, no code fences.
        \\
        \\Action schema:
        \\{"thought":"string","action":"navigate|click|type|scroll|extract|submit|wait|done","target":"CSS selector or URL","value":"string or empty","done":false}
        \\
        \\Actions:
        \\- navigate: target is a full URL, value is empty
        \\- click: target is a CSS selector, value is empty
        \\- type: target is a CSS selector, value is the text to type
        \\- scroll: target is "up" or "down", value is pixel amount as string
        \\- extract: target is a CSS selector, value is empty - extracts and records text content
        \\- submit: target is a CSS selector of a form, value is empty
        \\- wait: pause and wait for the page to load; target and value are empty
        \\- done: set done:true when the task is fully completed
        \\
        \\IMPORTANT - Cloudflare and bot challenges:
        \\If the page title contains "Just a moment", "Checking your browser", "Attention Required", or "Access denied", or if the URL contains "challenge", this is a bot protection page. Use the "wait" action and wait a few iterations for it to auto-resolve. Do NOT try to click any checkboxes on Cloudflare pages - just wait.
        \\If you are stuck on a challenge page for more than 4 iterations, try navigating to a different URL or subdomain to bypass it.
    ;

    const dom_truncated = if (dom_snapshot.len > 12000) dom_snapshot[0..12000] else dom_snapshot;

    const escaped_task = try escapeJsonString(allocator, task);
    defer allocator.free(escaped_task);
    const escaped_url = try escapeJsonString(allocator, current_url);
    defer allocator.free(escaped_url);
    const escaped_title = try escapeJsonString(allocator, page_title);
    defer allocator.free(escaped_title);
    const escaped_dom = try escapeJsonString(allocator, dom_truncated);
    defer allocator.free(escaped_dom);
    const escaped_history = try escapeJsonString(allocator, history);
    defer allocator.free(escaped_history);
    const escaped_system = try escapeJsonString(allocator, system_prompt);
    defer allocator.free(escaped_system);

    const user_content = try fmt.allocPrint(allocator,
        "Task: {s}\\nCurrent URL: {s}\\nPage title: {s}\\nIteration: {d}/40\\nPrevious actions: {s}\\nCurrent page state:\\n{s}",
        .{ task, current_url, page_title, iteration, history, dom_truncated },
    );
    defer allocator.free(user_content);

    const escaped_user = try escapeJsonString(allocator, user_content);
    defer allocator.free(escaped_user);

    const messages_json = try fmt.allocPrint(allocator,
        \\[{{"role":"system","content":"{s}"}},{{"role":"user","content":"{s}"}}]
    , .{ escaped_system, escaped_user });
    defer allocator.free(messages_json);

    return callLlmWithMessages(allocator, messages_json, api_key);
}

// =========================================================
// CDP WebSocket Client
// =========================================================

const CdpClient = struct {
    stream: net.Stream,
    next_id: u32,
    allocator: Allocator,

    fn connect(allocator: Allocator) !CdpClient {
        const target_url = try getChromeTargetUrl(allocator);
        defer allocator.free(target_url);

        const host = "localhost";
        const port: u16 = CHROME_DEBUG_PORT;

        const stream = try net.tcpConnectToAddress(try net.Address.parseIp4("127.0.0.1", port));
        errdefer stream.close();

        // 30-second receive timeout so call() never blocks forever
        const tv = posix.timeval{ .sec = 30, .usec = 0 };
        posix.setsockopt(stream.handle, posix.SOL.SOCKET, posix.SO.RCVTIMEO, mem.asBytes(&tv)) catch {};

        var key_bytes: [16]u8 = undefined;
        crypto.random.bytes(&key_bytes);
        var key_b64: [24]u8 = undefined;
        _ = std.base64.standard.Encoder.encode(&key_b64, &key_bytes);

        const handshake = try fmt.allocPrint(allocator,
            "GET {s} HTTP/1.1\r\n" ++
                "Host: {s}:{d}\r\n" ++
                "Upgrade: websocket\r\n" ++
                "Connection: Upgrade\r\n" ++
                "Sec-WebSocket-Key: {s}\r\n" ++
                "Sec-WebSocket-Version: 13\r\n" ++
                "\r\n",
            .{ target_url, host, port, key_b64 },
        );
        defer allocator.free(handshake);
        try stream.writeAll(handshake);

        var resp_buf: [2048]u8 = undefined;
        var resp_len: usize = 0;
        while (resp_len < resp_buf.len - 1) {
            var one: [1]u8 = undefined;
            const n = try stream.read(&one);
            if (n == 0) break;
            resp_buf[resp_len] = one[0];
            resp_len += 1;
            if (resp_len >= 4 and mem.eql(u8, resp_buf[resp_len - 4 .. resp_len], "\r\n\r\n")) break;
        }

        const resp = resp_buf[0..resp_len];
        if (!mem.startsWith(u8, resp, "HTTP/1.1 101")) {
            return error.WebSocketUpgradeFailed;
        }

        return CdpClient{
            .stream = stream,
            .next_id = 1,
            .allocator = allocator,
        };
    }

    fn deinit(self: *CdpClient) void {
        self.stream.close();
    }

    fn sendFrame(self: *CdpClient, data: []const u8) !void {
        var mask: [4]u8 = undefined;
        crypto.random.bytes(&mask);

        var header: [14]u8 = undefined;
        var hlen: usize = 2;
        header[0] = 0x81; // FIN + text opcode
        if (data.len <= 125) {
            header[1] = 0x80 | @as(u8, @intCast(data.len));
        } else if (data.len <= 65535) {
            header[1] = 0x80 | 126;
            header[2] = @intCast((data.len >> 8) & 0xFF);
            header[3] = @intCast(data.len & 0xFF);
            hlen = 4;
        } else {
            header[1] = 0x80 | 127;
            header[2] = 0;
            header[3] = 0;
            header[4] = 0;
            header[5] = 0;
            header[6] = @intCast((data.len >> 24) & 0xFF);
            header[7] = @intCast((data.len >> 16) & 0xFF);
            header[8] = @intCast((data.len >> 8) & 0xFF);
            header[9] = @intCast(data.len & 0xFF);
            hlen = 10;
        }
        header[hlen] = mask[0];
        header[hlen + 1] = mask[1];
        header[hlen + 2] = mask[2];
        header[hlen + 3] = mask[3];
        hlen += 4;

        const masked = try self.allocator.alloc(u8, data.len);
        defer self.allocator.free(masked);
        for (data, 0..) |b, i| {
            masked[i] = b ^ mask[i % 4];
        }

        try self.stream.writeAll(header[0..hlen]);
        try self.stream.writeAll(masked);
    }

    fn recvFrame(self: *CdpClient, out: *ArrayList(u8)) !bool {
        var header: [2]u8 = undefined;
        var n = try self.stream.readAll(&header);
        if (n < 2) return error.ConnectionClosed;

        const fin = (header[0] & 0x80) != 0;
        const opcode = header[0] & 0x0F;
        const masked = (header[1] & 0x80) != 0;
        var payload_len: usize = header[1] & 0x7F;

        if (payload_len == 126) {
            var ext: [2]u8 = undefined;
            n = try self.stream.readAll(&ext);
            if (n < 2) return error.ConnectionClosed;
            payload_len = (@as(usize, ext[0]) << 8) | ext[1];
        } else if (payload_len == 127) {
            var ext: [8]u8 = undefined;
            n = try self.stream.readAll(&ext);
            if (n < 8) return error.ConnectionClosed;
            payload_len = (@as(usize, ext[4]) << 24) | (@as(usize, ext[5]) << 16) | (@as(usize, ext[6]) << 8) | ext[7];
        }

        var mask_key: [4]u8 = undefined;
        if (masked) {
            n = try self.stream.readAll(&mask_key);
            if (n < 4) return error.ConnectionClosed;
        }

        if (payload_len > 10 * 1024 * 1024) return error.PayloadTooLarge;

        const payload = try self.allocator.alloc(u8, payload_len);
        defer self.allocator.free(payload);
        n = try self.stream.readAll(payload);
        if (n < payload_len) return error.ConnectionClosed;

        if (masked) {
            for (payload, 0..) |*b, i| {
                b.* ^= mask_key[i % 4];
            }
        }

        switch (opcode) {
            0x8 => return error.ConnectionClosed,
            0x9 => {
                var pong: [2]u8 = .{ 0x8A, 0x00 };
                _ = self.stream.writeAll(&pong) catch {};
            },
            0xA => {},
            else => {
                try out.appendSlice(payload);
            },
        }

        return fin;
    }

    fn recvMessage(self: *CdpClient) ![]const u8 {
        var buf = ArrayList(u8).init(self.allocator);
        errdefer buf.deinit();
        while (true) {
            const fin = try self.recvFrame(&buf);
            if (fin) break;
        }
        return buf.toOwnedSlice();
    }

    fn call(self: *CdpClient, method: []const u8, params: []const u8) ![]const u8 {
        const id = self.next_id;
        self.next_id += 1;

        const msg = try fmt.allocPrint(self.allocator, "{{\"id\":{d},\"method\":\"{s}\",\"params\":{s}}}", .{ id, method, params });
        defer self.allocator.free(msg);

        try self.sendFrame(msg);

        while (true) {
            const raw = try self.recvMessage();
            defer self.allocator.free(raw);

            const parsed = json.parseFromSlice(json.Value, self.allocator, raw, .{}) catch continue;
            defer parsed.deinit();

            if (parsed.value != .object) continue;

            const msg_id = parsed.value.object.get("id") orelse {
                continue;
            };
            if (msg_id != .integer) continue;
            if (@as(u32, @intCast(msg_id.integer)) == id) {
                return self.allocator.dupe(u8, raw);
            }
        }
    }

    fn navigate(self: *CdpClient, url: []const u8) !void {
        const escaped = try escapeJsonString(self.allocator, url);
        defer self.allocator.free(escaped);
        const params = try fmt.allocPrint(self.allocator, "{{\"url\":\"{s}\"}}", .{escaped});
        defer self.allocator.free(params);
        const result = try self.call("Page.navigate", params);
        defer self.allocator.free(result);
        std.time.sleep(3 * std.time.ns_per_s);
    }

    fn evaluate(self: *CdpClient, expression: []const u8) ![]const u8 {
        const escaped = try escapeJsonString(self.allocator, expression);
        defer self.allocator.free(escaped);
        const params = try fmt.allocPrint(self.allocator, "{{\"expression\":\"{s}\",\"returnByValue\":true,\"awaitPromise\":true}}", .{escaped});
        defer self.allocator.free(params);
        const result = try self.call("Runtime.evaluate", params);
        defer self.allocator.free(result);

        const parsed = try json.parseFromSlice(json.Value, self.allocator, result, .{});
        defer parsed.deinit();

        if (parsed.value != .object) return self.allocator.dupe(u8, "");
        const r = parsed.value.object.get("result") orelse return self.allocator.dupe(u8, "");
        if (r != .object) return self.allocator.dupe(u8, "");
        const rv = r.object.get("result") orelse return self.allocator.dupe(u8, "");
        if (rv != .object) return self.allocator.dupe(u8, "");
        const val = rv.object.get("value") orelse return self.allocator.dupe(u8, "");
        switch (val) {
            .string => return self.allocator.dupe(u8, val.string),
            .integer => return fmt.allocPrint(self.allocator, "{d}", .{val.integer}),
            .float => return fmt.allocPrint(self.allocator, "{d}", .{val.float}),
            else => return self.allocator.dupe(u8, ""),
        }
    }

